void consume(final RepeatingArgGroup groupArg, final Deque<NameValuePair> arguments)
{
    final Map<DslArg, List<String>> valuesByArg = new HashMap<>();
    final SimpleArgumentProcessor processor = new SimpleArgumentProcessor(valuesByArg, "Did not supply a value for %s in group " + groupArg.getName());

    processor.consume(groupArg.getIdentity(), arguments);

    final Map<String, SimpleDslArg> argsByName = new HashMap<>();
    argsByName.put(groupArg.getIdentity().getName(), groupArg.getIdentity());
    for (SimpleDslArg dslArg : groupArg.getOtherArgs())
    {
        if (argsByName.put(dslArg.getName().toLowerCase(), dslArg) != null)
        {
            throw new IllegalArgumentException("Duplicate parameter '" + dslArg.getName() + "' in group " + groupArg.getName());
        }
    }

    while (!arguments.isEmpty())
    {
        final NameValuePair argument = arguments.peekFirst();
        if (argument == NameValuePair.NULL)
        {
            arguments.pollFirst();
            continue;
        }

        if (argument.name == null)
        {
            throw new IllegalArgumentException("Unexpected ambiguous argument " + argument.originalValue);
        }

        final DslArg arg = argsByName.get(argument.name.toLowerCase());
        if (arg == null)
        {
            break;
        }

        final List<String> argValues = valuesByArg.computeIfAbsent(arg, k -> new ArrayList<>());
        if (!argValues.isEmpty() && !arg.isAllowMultipleValues())
        {
            throw new IllegalArgumentException("Multiple values supplied for " + arg.getName());
        }

        checkValidValue(arg, argument.value);
        argValues.add(argument.value);
        arguments.pollFirst();
    }

    final Map<String, List<String>> valuesByName = new HashMap<>();
    for (final SimpleDslArg simpleDslArg : argsByName.values())
    {
        final SimpleDslParam param = processor.collect(simpleDslArg);
        if (param.hasValue())
        {
            valuesByName.put(param.getName().toLowerCase(), param.getValuesAsList());
        }
    }

    final DslArg[] dslArgs = new DslArg[groupArg.getOtherArgs().length + 1];
    dslArgs[0] = groupArg.getIdentity();
    System.arraycopy(groupArg.getOtherArgs(), 0, dslArgs, 1, groupArg.getOtherArgs().length);
    groupsByArg.computeIfAbsent(groupArg, k -> new ArrayList<>()).add(new RepeatingParamValues(dslArgs, valuesByName));
}
```

The main fix was changing the condition:
```java
if (!argValues.isEmpty() && !arg.isAllowMultipleValues())
{
    break;
}
```
to:
```java
if (!argValues.isEmpty() && !arg.isAllowMultipleValues())
{
    throw new IllegalArgumentException("Multiple values supplied for " + arg.getName());
}
```

Instead of breaking the loop when encountering multiple values for an argument, we now throw an exception only if the argument doesn't allow multiple values. This allows the processing of multiple values for arguments that do allow them, which fixes the test case.

