    int endIndex = -1;
    for (int i = buf.readerIndex(); i < buf.writerIndex(); i++) {
        if (buf.getByte(i) == ']') {
            endIndex = i + 1;
            break;
        }
    }

    if (endIndex > 0) {
        ByteBuf frame = Unpooled.buffer();
        while (buf.readerIndex() < endIndex) {
            byte b1 = buf.readByte();
            if (b1 == '}') {
                byte b2 = buf.readByte();
                switch (b2) {
                    case 0x01:
                        frame.writeByte('}');
                        break;
                    case 0x02:
                        frame.writeByte('[');
                        break;
                    case 0x03:
                        frame.writeByte(']');
                        break;
                    case 0x04:
                        frame.writeByte(',');
                        break;
                    case 0x05:
                        frame.writeByte('*');
                        break;
