                offset = -offset;
            }
            if (deviceSession != null) {
                TimeZone timeZone = deviceSession.get(DeviceSession.KEY_TIMEZONE);
                if (timeZone.getRawOffset() == 0) {
                    timeZone.setRawOffset(offset * 1000);
                    deviceSession.set(DeviceSession.KEY_TIMEZONE, timeZone);
                }
