                    String data = buf.readCharSequence(buf.readUnsignedByte(), StandardCharsets.US_ASCII).toString();
                    buf.readUnsignedByte(); // alarm
                    buf.readUnsignedByte(); // swiped
                    position.set(Position.KEY_CARD, data.trim());
